for pos in positions:
    with open('/app/alpine.iso','rb') as f:
        f.seek(max(0,pos))
        chunk=f.read(1600)
    text=chunk.decode('latin1', errors='replace')
    # print only runs of mostly printable
    import re
    out=[]
    cur=''
    for ch in text:
        if 32<=ord(ch)<127 or ch in '\n\r\t':
            cur+=ch
        else:
            if cur.strip():
                out.append(cur.strip())
            cur=''
    if cur.strip():
        out.append(cur.strip())
